package com.loopers.application.payment;import com.loopers.domain.payment.*;import com.loopers.support.error.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.util.*;
// Hides: one-dispatch fencing and UNKNOWN reconciliation sequencing.
@Component @RequiredArgsConstructor public class PaymentFacade{private static final String USER="135135";private final PaymentIntentRepository repo;private final PaymentGateway gateway;
 @Transactional public PaymentIntent dispatch(long orderId,String attempt,long amount){Optional<PaymentIntent> existing=repo.findByAttempt(orderId,attempt);if(existing.isPresent())return existing.get();PaymentIntent p=repo.save(new PaymentIntent(orderId,attempt,amount));p.requested();try{PaymentGateway.Result r=gateway.create(USER,new PaymentGateway.Request(p.getProviderOrderId(),"SAMSUNG","1234-1234-1234-1234",amount,"http://localhost:8080/api/v1/payments/callback"));p.settle(r.transactionKey(),PaymentIntent.Status.valueOf(r.status()));}catch(RuntimeException e){p.unknown();}return repo.save(p);}
 @Transactional public PaymentIntent reconcile(long id){PaymentIntent p=repo.find(id).orElseThrow(()->new CoreException(ErrorType.NOT_FOUND));if(p.getStatus()!=PaymentIntent.Status.UNKNOWN)return p;List<PaymentGateway.Result> found=gateway.findByOrderId(USER,p.getProviderOrderId());if(found.size()==1)p.settle(found.getFirst().transactionKey(),PaymentIntent.Status.valueOf(found.getFirst().status()));else if(found.size()>1)throw new CoreException(ErrorType.CONFLICT,"multiple provider effects");return repo.save(p);}
 @Transactional public PaymentIntent callback(String orderId,String transactionKey,String status){PaymentIntent p=repo.findByProviderOrderId(orderId).orElseThrow(()->new CoreException(ErrorType.NOT_FOUND));p.settle(transactionKey,PaymentIntent.Status.valueOf(status));return repo.save(p);}
}
